import type { TranslationFinding } from '@tla/shared';
import { createFinding } from '../engines/direct/attribute-transformer.js';

// ---------------------------------------------------------------------------
// Credential key set
// ---------------------------------------------------------------------------

const CREDENTIAL_KEYS: ReadonlySet<string> = new Set([
  'access_key',
  'secret_key',
  'token',
  'session_token',
  'role_arn',
  'external_id',
  'profile',
  'shared_credentials_file',
  'shared_credentials_files',
  'web_identity_token_file',
  'web_identity_token',
  'assume_role_with_web_identity',
]);

const RESOURCE_ID = 'terraform.backend';

// ---------------------------------------------------------------------------
// Scrubber result
// ---------------------------------------------------------------------------

export interface ScrubResult {
  readonly scrubbed: Record<string, unknown>;
  readonly findings: readonly TranslationFinding[];
}

// ---------------------------------------------------------------------------
// Scrubber
// ---------------------------------------------------------------------------

/**
 * Removes credential-related keys from a backend attribute map.
 * Returns the scrubbed map and an info finding for each removed key.
 */
export function scrubCredentials(
  attributes: Record<string, unknown>,
): ScrubResult {
  const scrubbed: Record<string, unknown> = {};
  const findings: TranslationFinding[] = [];

  for (const key of Object.keys(attributes).sort()) {
    if (CREDENTIAL_KEYS.has(key)) {
      findings.push(
        createFinding(
          RESOURCE_ID,
          'info',
          'STATE_CREDENTIAL_SCRUBBED',
          `Credential attribute '${key}' removed from backend configuration`,
        ),
      );
    } else {
      scrubbed[key] = attributes[key];
    }
  }

  return { scrubbed, findings };
}
